<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { categoryApi, documentApi } from '@/api'
import type { Category, DocumentItem } from '@/types'
const rows = ref<DocumentItem[]>([]); const categories = ref<Category[]>([]); const loading = ref(false); const dialog = ref(false); const editingId = ref<number | null>(null); const saving = ref(false); const selectedFile = ref<File | null>(null); const fileInput = ref<HTMLInputElement>()
const page = ref(1); const total = ref(0); const filters = reactive({ keyword: '', category_id: undefined as number | undefined, status: '' })
const form = reactive({ title: '', category_id: undefined as number | undefined, summary: '', keywords: '', source: '', document_no: '', effective_date: '', expire_date: '', allow_download: true, sort_order: 0, status: 'DRAFT' })
function statusType(status: string) { return status === 'PUBLISHED' ? 'success' : status === 'OFFLINE' ? 'warning' : 'info' }
async function load() { loading.value = true; try { const response = await documentApi.list({ ...filters, page: page.value, page_size: 20 }); rows.value = response.data.data.list; total.value = response.data.pagination?.total || 0 } catch (e) { ElMessage.error((e as Error).message) } finally { loading.value = false } }
async function loadCategories() { categories.value = (await categoryApi.list()).data.data.list }
function resetForm() { Object.assign(form, { title: '', category_id: undefined, summary: '', keywords: '', source: '', document_no: '', effective_date: '', expire_date: '', allow_download: true, sort_order: 0, status: 'DRAFT' }); selectedFile.value = null; if (fileInput.value) fileInput.value.value = '' }
function openCreate() { editingId.value = null; resetForm(); dialog.value = true }
async function openEdit(row: DocumentItem) {
  try { const response = await documentApi.detail(row.document_id); const d = response.data.data.document; editingId.value = d.document_id; Object.assign(form, { title: d.title, category_id: d.category_id, summary: d.summary, keywords: d.keywords, source: d.source_department, document_no: d.document_no, effective_date: d.effective_date, expire_date: d.expire_date, allow_download: d.allow_download, sort_order: d.sort_order || 0 }); selectedFile.value = null; if (fileInput.value) fileInput.value.value = ''; dialog.value = true } catch (e) { ElMessage.error((e as Error).message) }
}
function chooseFile(event: Event) { const files = (event.target as HTMLInputElement).files; selectedFile.value = files?.[0] || null }
async function save() {
  if (!form.title.trim() || !form.category_id) return ElMessage.warning('请填写标题和分类')
  if (!editingId.value && !selectedFile.value) return ElMessage.warning('请选择要上传的文档')
  const data = new FormData()
  for (const [key, value] of Object.entries(form)) if (value !== '' && value !== undefined) data.append(key, String(value))
  if (selectedFile.value) data.append('file', selectedFile.value)
  saving.value = true
  try { if (editingId.value) await documentApi.update(editingId.value, data); else await documentApi.create(data); ElMessage.success(editingId.value ? '文档已更新' : '文档已保存'); dialog.value = false; await load() } catch (e) { ElMessage.error((e as Error).message) } finally { saving.value = false }
}
async function setStatus(row: DocumentItem, status: string) { try { await documentApi.setStatus(row.document_id, status); ElMessage.success(status === 'PUBLISHED' ? '已发布' : '状态已更新'); await load() } catch (e) { ElMessage.error((e as Error).message) } }
async function remove(row: DocumentItem) { try { await ElMessageBox.confirm(`确定删除“${row.title}”吗？`, '删除确认', { type: 'warning' }); await documentApi.remove(row.document_id); ElMessage.success('文档已逻辑删除'); await load() } catch (e: any) { if (e !== 'cancel' && e !== 'close') ElMessage.error(e.message || '操作失败') } }
onMounted(() => { load(); loadCategories() })
</script>
<template>
  <div class="page-stack">
    <div class="panel"><div class="filter-bar"><el-input v-model="filters.keyword" placeholder="搜索文档标题" clearable style="width:220px" @keyup.enter="page=1;load()" /><el-select v-model="filters.category_id" placeholder="全部分类" clearable style="width:160px"><el-option v-for="item in categories" :key="item.category_id" :label="item.name" :value="item.category_id" /></el-select><el-select v-model="filters.status" placeholder="全部状态" clearable style="width:140px"><el-option label="草稿" value="DRAFT" /><el-option label="已发布" value="PUBLISHED" /><el-option label="已下架" value="OFFLINE" /></el-select><el-button type="primary" @click="page=1;load()">筛选</el-button><el-button type="primary" plain @click="openCreate">上传文档</el-button></div></div>
    <div class="panel"><div class="panel-head"><div><h3>知识文档</h3><p>发布后移动端即可查看并进行问答</p></div><span class="muted">共 {{ total }} 篇</span></div>
      <el-table v-loading="loading" :data="rows" stripe><el-table-column prop="title" label="标题" min-width="210"><template #default="{ row }"><div class="doc-title"><strong>{{ row.title }}</strong><small>{{ row.file_type }} · {{ row.category_name }}</small></div></template></el-table-column><el-table-column label="发布状态" width="110"><template #default="{ row }"><el-tag :type="statusType(row.status)">{{ row.status }}</el-tag></template></el-table-column><el-table-column prop="view_count" label="浏览" width="80" /><el-table-column prop="updated_at" label="更新时间" width="180" /><el-table-column label="操作" width="250" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-button v-if="row.status !== 'PUBLISHED'" link type="success" @click="setStatus(row, 'PUBLISHED')">发布</el-button><el-button v-if="row.status === 'PUBLISHED'" link type="warning" @click="setStatus(row, 'OFFLINE')">下架</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
      <div class="pager"><el-pagination v-model:current-page="page" layout="prev, pager, next" :page-size="20" :total="total" @current-change="load" /></div>
    </div>
    <el-dialog v-model="dialog" :title="editingId ? '编辑文档' : '上传文档'" width="760px"><el-form label-position="top"><div class="form-grid"><el-form-item label="文档标题" class="span-2"><el-input v-model="form.title" maxlength="200" /></el-form-item><el-form-item label="所属分类"><el-select v-model="form.category_id" style="width:100%"><el-option v-for="item in categories.filter(x => x.status === 'ENABLED')" :key="item.category_id" :label="item.name" :value="item.category_id" /></el-select></el-form-item><el-form-item label="来源部门"><el-input v-model="form.source" /></el-form-item><el-form-item label="摘要" class="span-2"><el-input v-model="form.summary" type="textarea" :rows="2" maxlength="500" /></el-form-item><el-form-item label="关键词"><el-input v-model="form.keywords" placeholder="逗号分隔" /></el-form-item><el-form-item label="文号"><el-input v-model="form.document_no" /></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="form.effective_date" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item><el-form-item label="失效日期"><el-date-picker v-model="form.expire_date" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sort_order" :min="0" /></el-form-item><el-form-item label="允许下载"><el-switch v-model="form.allow_download" /></el-form-item><el-form-item v-if="!editingId" label="发布状态"><el-radio-group v-model="form.status"><el-radio value="DRAFT">保存草稿</el-radio><el-radio value="PUBLISHED">立即发布</el-radio></el-radio-group></el-form-item><el-form-item label="文档文件" :class="editingId ? 'span-2' : 'span-2'"><input ref="fileInput" type="file" accept=".pdf,.docx,.txt,.md" @change="chooseFile" /><p class="muted">{{ editingId ? '不选择文件则保留原文件；选择新文件会更新文档内容。' : '支持 PDF、DOCX、TXT、MD，默认上限 20MB。' }}</p></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
  </div>
</template>
